import { SOGNodeType, SOGEdgeType } from '../../sog/sog-core-schema';
/**
 * global-evolution.ts — 全局进化 Layer 3 (Phase C3)
 *
 * 跨组织本体模式学习。仅基于已确认的实体关联训练。
 * 候选关联不进Layer 3——这是硬边界。
 */
import type { GraphStore } from './graph-store';
import type { EdgeType, NodeType } from './types';
import { createLogger } from '../../infra/logger';

const log = createLogger('diagnosis/global-evolution');

export interface CrossOrgPattern {
  id: string;
  patternType: 'edge_weight_benchmark' | 'node_type_frequency' | 'community_structure';
  description: string;
  confidence: number;
  /** 参与组织数 (匿名化) */
  orgCount: number;
  /** 模式适用的行业 */
  industries: string[];
  /** 生成的基准值 */
  benchmarks: Record<string, number>;
  /** 生成的诊断规则建议 */
  suggestedRule?: { name: string; condition: string; severity: 'high' | 'medium' | 'low'; recommendation: string };
  discoveredAt: string;
}

const patternStore: CrossOrgPattern[] = [];

/** 从多个组织的匿名化本体图中发现跨组织模式 */
export function discoverCrossOrgPatterns(
  stores: Array<{ store: GraphStore; graph: string; industry: string }>,
): CrossOrgPattern[] {
  const newPatterns: CrossOrgPattern[] = [];
  if (stores.length < 3) return newPatterns; // 最小样本量门禁

  // ── Edge weight benchmarks ──
  const edgeTypes: EdgeType[] = [SOGEdgeType.INTERACTS_WITH, SOGEdgeType.BELONGS_TO];
  for (const et of edgeTypes) {
    const weights: number[] = [];
    for (const { store, graph } of stores) {
      const edges = store.queryEdges(et, undefined, undefined, graph);
      if (edges.length > 0) weights.push(edges.reduce((s, e) => s + e.weight, 0) / edges.length);
    }
    if (weights.length >= 3) {
      const avg = weights.reduce((s, w) => s + w, 0) / weights.length;
      const std = Math.sqrt(weights.reduce((s, w) => s + (w - avg) ** 2, 0) / weights.length);
      newPatterns.push({
        id: `pat_${Date.now().toString(36)}`,
        patternType: 'edge_weight_benchmark',
        description: `${et} 边权重跨组织基准: 均值 ${avg.toFixed(2)}, 标准差 ${std.toFixed(2)}`,
        confidence: Math.min(0.5 + stores.length * 0.05, 0.9),
        orgCount: stores.length,
        industries: [...new Set(stores.map(s => s.industry))],
        benchmarks: { mean: avg, std, p25: avg - std, p75: avg + std },
        suggestedRule: {
          name: `${et} 权重偏低告警`,
          condition: `${et} 边权重 < ${(avg - std * 1.5).toFixed(2)}`,
          severity: 'medium',
          recommendation: `${et} 边权重低于跨组织基准1.5个标准差, 建议关注协作健康度`,
        },
        discoveredAt: new Date().toISOString(),
      });
    }
  }

  // ── Node type frequency ──
  const nodeTypes: NodeType[] = [SOGNodeType.PERSON, SOGNodeType.TEAM, SOGNodeType.AGENT, SOGNodeType.TOOL];
  for (const nt of nodeTypes) {
    const counts = stores.map(({ store, graph }) => store.queryNodes(nt, undefined, graph).length);
    const avg = counts.reduce((s, c) => s + c, 0) / counts.length;
    if (avg > 0) {
      newPatterns.push({
        id: `pat_${Date.now().toString(36)}_${nt}`,
        patternType: 'node_type_frequency',
        description: `${nt} 节点平均数量: ${avg.toFixed(0)} (${stores.length}组织)`,
        confidence: 0.7,
        orgCount: stores.length,
        industries: [...new Set(stores.map(s => s.industry))],
        benchmarks: { avgCount: avg },
        discoveredAt: new Date().toISOString(),
      });
    }
  }

  patternStore.push(...newPatterns);
  log.info({ newPatterns: newPatterns.length, orgCount: stores.length }, '[global-evolution] Patterns discovered');
  return newPatterns;
}

export function getPatterns(industry?: string): CrossOrgPattern[] {
  if (!industry) return [...patternStore];
  return patternStore.filter(p => p.industries.includes(industry));
}

export function clearEvolution(): void { patternStore.length = 0; }
